from collections import deque


class ConnectGame:
    """A game of Hex / Polygon (CON-TAC-TIX).

    Player ``O`` plays from top to bottom and player ``X`` plays from
    left to right.  The board is a parallelogram of hexagonal fields; each
    row is shifted one cell to the right relative to the row above it.
    """

    def __init__(self, board):
        # Each row is a list of cell characters.  Leading whitespace in the
        # source string only encodes the row shift, so splitting on any
        # whitespace yields the cells in column order.
        self.board = [line.split() for line in board.splitlines() if line.strip()]

    def get_winner(self):
        if self._reaches("O"):
            return "O"
        if self._reaches("X"):
            return "X"
        return ""

    def _reaches(self, player):
        """Return True if ``player`` has a connected path between their sides."""
        rows = len(self.board)
        if rows == 0:
            return False

        if player == "O":
            # O plays from top to bottom: start on the top row, goal the bottom row.
            start = [(0, c) for c in range(len(self.board[0])) if self.board[0][c] == player]

            def is_goal(r, c):
                return r == rows - 1
        else:
            # X plays from left to right: start on the left edge, goal the right edge.
            start = [(r, 0) for r in range(rows) if self.board[r][0] == player]

            def is_goal(r, c):
                return c == len(self.board[r]) - 1

        seen = set(start)
        queue = deque(start)
        while queue:
            r, c = queue.popleft()
            if is_goal(r, c):
                return True
            for nr, nc in self._neighbors(r, c):
                if (nr, nc) not in seen and self.board[nr][nc] == player:
                    seen.add((nr, nc))
                    queue.append((nr, nc))
        return False

    def _neighbors(self, r, c):
        """Yield the six hex neighbours of cell ``(r, c)``.

        Because each row is shifted one cell to the right, the diagonal
        neighbours of ``(r, c)`` are ``(r - 1, c)``, ``(r - 1, c + 1)``,
        ``(r + 1, c - 1)`` and ``(r + 1, c)``.
        """
        rows = len(self.board)
        for dr, dc in ((0, -1), (0, 1), (-1, 0), (-1, 1), (1, -1), (1, 0)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < len(self.board[nr]):
                yield nr, nc

